import json
from pathlib import Path

P=Path(__file__).parent
lessons=[]
def section(title,body,example=None):
    d={'title':title,'body':body}
    if example:d['example']=example
    return d
def example(title,statement,steps,answer):return dict(title=title,statement=statement,steps=steps,answer=answer)
def exercise(id,title,statement,hint,steps,answer,level='Application'):return dict(id=id,title=title,level=level,statement=statement,hint=hint,steps=steps,answer=answer)
def video(title,*segments):return {'title':title,'segments':[dict(text=a,equation=b,note=c) for a,b,c in segments]}
def lesson(id,title,titleAr,intro,sections,summary,pitfalls,exercises,videoLesson=None,**extra):
    d=dict(id=id,title=title,titleAr=titleAr,domain='analyse',tracks=['pc','sm'],level='Fondamentaux du bac',duration=40,prerequisites=[],goals=[],intro=intro,sections=sections,summary=summary,pitfalls=pitfalls,exercises=exercises,videos=[],quiz=[],tags=[id,title],**extra)
    if videoLesson:d['videoLesson']=videoLesson
    lessons.append(d);return d

l=lesson('limites','Limites et comportements asymptotiques','النهايات والسلوك قرب الحدود',
 'الليميت كتجاوب على سؤال: القيم ديال الدالة لفين كتمشي ملي المتغيّر كيقرّب لواحد العدد، أو كيكبر بزاف؟ كنفرقو بين القيمة فالنقطة والسلوك حداها. هاد الفرق هو الأساس باش نفهمو الاستمرارية والمقارب.',[
 section('1. Domaine, voisinage et limites latérales',r'<p>أول خطوة هي المجال \(D_f\). فالكسر المقام ما يكونش صفر، تحت الجذر التربيعي التعبير موجب أو منعدم، وداخل \(\ln\) موجب تماماً. كنحسبو النهاية غير من الجهات اللي فيها الدالة معرّفة.</p><p>\(x\to a^-\) كيعني من اليسار و\(x\to a^+\) من اليمين. النهاية فـ \(a\) كتكون \(\ell\) إلا كانت نهايتا الجهتين موجودتين ومتساويتين، ملي المجال كيسمح بالجوج. قيمة \(f(a)\) ممكن ما تكونش معرّفة أصلاً.</p>',example('نفس النقطة، جوج سلوكات',r'دراسة \(f(x)=1/x\) قرب الصفر.', [r'إذا \(x>0\)، الكسر موجب وكيتجاوز أي عدد موجب ملي \(x\to0^+\).',r'إذا \(x<0\)، الكسر سالب و\(f(x)\to-\infty\) ملي \(x\to0^-\).'],r'\(\lim_{x\to0^+}1/x=+\infty\) و\(\lim_{x\to0^-}1/x=-\infty\). ما كايناش نهاية واحدة فالصفر.')),
 section('2. Opérations et signes',r'<p>إلا كانت \(f\to\ell\) و\(g\to m\) بنهايات منتهية، كنحسبو نهاية المجموع والجداء بالتعويض. فالقسمة خاص \(m\ne0\). إلا كان المقام كيمشي للصفر والبسط لعدد غير منعدم، كنقراو إشارة المقام والبسط باش نعرفو \(+\infty\) أو \(-\infty\).</p><p>ما كنعتابروش \(\infty\) عدداً عادياً. تعابير بحال \(0/0\)، \(\infty/\infty\) و\(\infty-\infty\) خاصها تحويل مناسب قبل الاستنتاج. النهاية ديال تركيب كتتحسب بعد التحقق من مجال التركيب ومن النهاية المطلوبة للدالة الخارجية.</p>'),
 section('3. Limites usuelles et encadrement',r'<p>ملي \(x\to+\infty\)، عندنا \(1/x^p\to0\) لكل \(p>0\). وملي \(x\to0\)، \(\sin x/x\to1\) باستعمال radians. بالنسبة للوغاريتم والأسية، كنستعملو \(\ln x/x^\alpha\to0\) و\(x^\alpha e^{-x}\to0\) فـ \(+\infty\)، لأي \(\alpha>0\).</p><p>مبرهنة الحصر: إلا \(u(x)\le f(x)\le v(x)\) قرب النقطة و\(u,v\to\ell\)، إذن \(f\to\ell\). مثلاً \(-|x|\le x\sin(1/x)\le|x|\)، وبالتالي النهاية صفر، بلا حاجة نعرفو نهاية \(\sin(1/x)\) اللي ما كايناش.</p>'),
 section('4. Polynômes et quotients à l’infini',r'<p>فكثير الحدود، الحد ذو أكبر درجة هو اللي كيتحكم فالسلوك فـ \(\pm\infty\). كنخرجو أكبر قوة أو كنقسمو عليها. فالكسر \(P/Q\)، إلا درجة البسط أصغر من المقام النهاية صفر. إلا متساويتين النهاية نسبة المعاملين الرئيسيين. إلا درجة البسط أكبر، كنراعيوا الفرق فالدراجات والإشارة.</p>',example('نهاية كسر عند اللانهاية',r'\[\lim_{x\to+\infty}\frac{2x^3-x}{x^3+4}.\]',[r'كنقسمو البسط والمقام على \(x^3\)، اللي غير منعدم بالنسبة لـ \(x\) كبير.',r'كيولي الكسر \(\frac{2-1/x^2}{1+4/x^3}\).',r'\(1/x^2\to0\) و\(4/x^3\to0\)، والمقام كيمشي لواحد.'],r'النهاية هي \(2\).')),
 section('5. Asymptotes et position relative',r'<p>إلا \(f(x)\to\pm\infty\) ملي \(x\to a\) من شي جهة، فـ \(x=a\) مقارب عمودي. إلا \(f(x)\to b\) فـ \(+\infty\) أو \(-\infty\)، فـ \(y=b\) مقارب أفقي من هديك الجهة. المستقيم \(y=ax+b\) مقارب مائل إلا \(f(x)-(ax+b)\to0\).</p><p>باش نعرفو شكون فوق الآخر، كنقراو إشارة الفرق \(f(x)-(ax+b)\). ما كافيش نحسبو \(f(x)/x\to a\) بوحدها، خاص حتى \(f(x)-ax\to b\). الرسمة كتعاون ولكن البرهان هو النهاية والإشارة.</p>')],
 [r'المجال والإشارة قبل التعويض.',r'نهاية الجهتين كتحتاج نفس النتيجة.',r'\(\lim f/g=\ell/m\) إذا \(m\ne0\).',r'فـ \(P/Q\) عند اللانهاية، قارن الدرجات.',r'المقارب المائل كيتحقق بـ \(f(x)-(ax+b)\to0\).'],
 ['ما تخلطش بين قيمة الدالة ونهايتها.','القسمة على مقدار كيقرّب للصفر كتحتاج دراسة الإشارة.',r'حدود \(\sin x/x\) كتستعمل الزاوية بالـ radians.'],[
 exercise('lim-1','نهاية جانبية',r'حسب \(\lim_{x\to2^+}\frac{3}{x-2}\).','حدّد إشارة المقام.',[r'\(x-2\to0^+\).',r'البسط ثابت موجب، والمقام موجب وصغير.'],r'\(+\infty\).'),
 exercise('lim-2','مقارنة الدرجات',r'حسب \(\lim_{x\to+\infty}\frac{5x+1}{x^2+3}\).','قسم على مربع إكس.',[r'الكسر هو \(\frac{5/x+1/x^2}{1+3/x^2}\).',r'البسط كيمشي للصفر والمقام لواحد.'],r'\(0\).'),
 exercise('lim-3','مبرهنة الحصر',r'حسب \(\lim_{x\to0}x^2\cos(1/x)\).','استعمل أن جيب التمام بين ناقص واحد وواحد.',[r'\(-1\le\cos(1/x)\le1\) بالنسبة لـ \(x\ne0\).',r'\(-x^2\le x^2\cos(1/x)\le x^2\).',r'الطرفان كيمشيو للصفر، فنطبق الحصر.'],r'\(0\).')],
 video('نهاية كسر عند اللانهاية',
 ('بغينا ليميت جوج إكس مكعب ناقص إكس، على إكس مكعب زائد ربعة، ملي إكس كيمشي لزائد لانفيني. كنبدأو بتحديد الشكل.',r'\lim_{x\to+\infty}\frac{2x^3-x}{x^3+4}','Identifier la forme'),
 ('البسط والمقام بجوج كيمشيو لزائد لانفيني. إذن التعويض المباشر ما كيحددش النتيجة، وخاصنا نبدلو الكتابة ديال الكسر.',r'\frac{\infty}{\infty}','Une forme indéterminée'),
 ('أكبر قوة موجودة هي إكس مكعب. كنقسمو عليها البسط والمقام كاملين، ماشي غير بعض الحدود، باش نحافظو على نفس الكسر.',r'\frac{2-1/x^2}{1+4/x^3}','Diviser les deux termes par x³'),
 ('واحد على إكس مربع كيمشي للصفر، وربعة على إكس مكعب حتى هي للصفر. المقام الجديد كيمشي لواحد، اللي ماشي صفر.',r'\frac{2-0}{1+0}','Passer à la limite'),
 ('إذن النتيجة هي جوج. ونقدرو نراقبوها حيت الدرجتين متساويتين، والنسبة بين المعاملين الرئيسيين هي جوج على واحد.',r'\boxed{2}','Conclure')))
l['goals']=['نحدّد المجال والنهايات الجانبية.','نختار القاعدة المناسبة وننتبه للأشكال غير المحددة.','نثبت المقاربات بالحدود.'];l['quiz']=[dict(question='إذا كانت النهايتان الجانبيتان مختلفتين، واش كاينة نهاية واحدة؟',choices=['نعم دائماً','لا','غير إلا كانت f(a)=0'],correct=1,explanation='وجود قيمة فالنقطة ما كيصلحش اختلاف السلوك ديال الجهتين.')]

forms=[
 ('0/0',r'\lim_{x\to2}\frac{x^2-4}{x-2}=4',r'<p>التعويض كيعطي صفر على صفر. كنحلّلو \(x^2-4=(x-2)(x+2)\)، ثم كنختازلو العامل بالنسبة لـ \(x\ne2\). التعبير كيولي \(x+2\)، والنهاية \(4\). الدالة الأصلية كتبقى غير معرّفة فـ \(2\).</p>'),
 ('∞/∞',r'\lim_{x\to+\infty}\frac{3x^2+2x}{x^2-1}=3',r'<p>كنقسمو البسط والمقام على \(x^2\): \(\frac{3+2/x}{1-1/x^2}\to3\). هاد الطريقة مناسبة لكثيرات الحدود. ما كنختازلوش حدود مجموع إلا إلى حوّلناها لعوامل.</p>'),
 ('∞ − ∞',r'\lim_{x\to+\infty}(\sqrt{x^2+x}-x)=\frac12',r'<p>كنضربو ونقسمو فالمرافق \(\sqrt{x^2+x}+x\). كيولي التعبير \(\frac{x}{\sqrt{x^2+x}+x}=\frac1{\sqrt{1+1/x}+1}\to\frac12\). استعملنا \(x>0\). بصفة عامة \(\sqrt{x^2}=|x|\).</p>'),
 ('0 × ∞',r'\lim_{x\to0^+}x\ln(1/x)=0',r'<p>كنحطّو \(t=1/x\)، فـ \(t\to+\infty\). التعبير كيولي \(\ln t/t\to0\)، وهي limite classique ديال croissance comparée. ونستنتجو حتى \(x\ln x\to0\)، ولكن بقيم سالبة قرب الصفر من اليمين.</p>'),
 ('1^∞',r'\lim_{x\to+\infty}(1+1/x)^x=e',r'<p>نسمي التعبير \(y>0\). عندنا \(\ln y=x\ln(1+1/x)\). بوضع \(u=1/x\) كنلقاو \(\ln y=\ln(1+u)/u\to1\). باستمرارية الأسية \(y=e^{\ln y}\to e\). هادي نتيجة المثال، ماشي قيمة عامة للشكل.</p>'),
 ('0^0',r'\lim_{x\to0^+}x^x=1',r'<p>الأساس موجب. كنحطّو \(y=x^x\)، و\(\ln y=x\ln x\to0\). إذن \(y\to e^0=1\). كنحسبو نهاية، وما كنعطيوش تعريف عام للكتابة \(0^0\).</p>'),
 ('∞^0',r'\lim_{x\to+\infty}x^{1/x}=1',r'<p>\(\ln(x^{1/x})=\ln x/x\to0\)، ومن بعد كنرجعو للأسية، فالنهاية \(1\). خاص الأساس يكون موجب قرب الجهة اللي خدامين فيها.</p>')]
l=lesson('formes-indeterminees','Les 7 formes indéterminées','الأشكال غير المحددة السبعة',
 'نفس الشكل يقدر يعطي نهايات مختلفة. مثلاً قرب الصفر من اليمين، إكس على إكس كيعطي واحد، إكس مربع على إكس كيعطي صفر، وإكس على إكس مربع كيمشي لزائد لانفيني. الشكل وحده ماشي جواب.',
 [section(f'{i+1}. {name}',r'\['+eq+r'\]'+body) for i,(name,eq,body) in enumerate(forms)]+
 [section('اختيار الطريقة حسب التعبير',r'<p>مع كثيرات الحدود: factorisation أو مقارنة الدرجات. مع فرق الجذور: المرافق. مع الدوال المثلثية: الحدود الكلاسيكية بشرط radians. مع الجداء: حوّلو لكسر أو بدّل المتغيّر. مع القوة \(u^v\) والأساس موجب: حسب نهاية \(v\ln u\) ومن بعد استعمل الأسية. إشارات بحال \(0\times(-\infty)\) داخلة فنفس العائلة بعد معالجة الإشارة.</p>')],
 ['الشكل غير المحدد ما كيحدّدش النتيجة.',r'الاختزال كيكون على عامل غير منعدم.',r'\(\sqrt{x^2}=|x|\).',r'اللوغاريتم فالقوى كيحتاج أساساً موجباً.',r'\(\ln y\to L\) منتهية كتعطي \(y\to e^L\).'],
 ['ما تقولش صفر على صفر كيساوي صفر أو واحد.','ما تختازلش حدود مجموعة، اختازل عوامل.','ما تعممش نتيجة مثال على الشكل كامل.'],[
 exercise('fi-1','التحليل',r'حسب \(\lim_{x\to3}\frac{x^2-9}{x-3}\).','فرق بين جوج مربعات.',[r'\(x^2-9=(x-3)(x+3)\).',r'بالنسبة لـ \(x\ne3\)، الكسر هو \(x+3\).'],r'\(6\).'),
 exercise('fi-2','المرافق',r'حسب \(\lim_{x\to0}\frac{\sqrt{1+x}-1}{x}\).','ضرب وقسم فالمرافق.',[r'المجال قرب الصفر هو \(x>-1\)، وبالنسبة للكسر \(x\ne0\).',r'\(\frac{\sqrt{1+x}-1}{x}=\frac{1}{\sqrt{1+x}+1}\).'],r'\(1/2\).'),
 exercise('fi-3','قوة متغيرة',r'حسب \(\lim_{x\to+\infty}(1+2/x)^x\).','لوغاريتم التعبير، ثم حط يو يساوي جوج على إكس.',[r'\(y=(1+2/x)^x>0\) لـ \(x>0\).',r'\(\ln y=x\ln(1+2/x)=2\frac{\ln(1+u)}u\to2\).'],r'\(e^2\).','Approfondissement')])
l['duration']=55;l['prerequisites']=['limites','logarithme','exponentielle'];l['goals']=['نتعرّف على العائلات السبع.','نفهم علاش التحويل ضروري.','نحل أمثلة بدون قاعدة L’Hôpital.'];l['quiz']=[dict(question='شنو كنستنتجو مباشرة من الشكل ∞ − ∞؟',choices=['النتيجة صفر','النتيجة واحد','خاص تحويل أو معلومة إضافية'],correct=2,explanation='مثال فرق الجذور هنا عطى النصف، وأمثلة أخرى تعطي نتائج أخرى.')]

l=lesson('continuite','Continuité et théorème des valeurs intermédiaires','الاستمرارية ومبرهنة القيم الوسيطية',
 'الدالة مستمرة فواحد النقطة ملي السلوك ديالها حدا النقطة متوافق مع القيمة اللي خذات تماك. ماشي غير رسمة ما فيهاش انقطاع، بل شرط حسابي نقدر نتحققو منو.',[
 section('1. Continuité en un point et sur un intervalle',r'<p>باش تكون \(f\) مستمرة فـ \(a\)، خاص \(a\in D_f\) و\(\lim_{x\to a}f(x)=f(a)\). كنستعملو نهاية من داخل المجال فحدود المجال. الاستمرارية على مجال كتعني تحقق الشرط فكل نقطة منه.</p><p>كثيرات الحدود مستمرة على \(\mathbb R\)، والكسور على مجال تعريفها. \(\sqrt{x}\) مستمرة على \([0,+\infty[\)، و\(\ln x\) على \(]0,+\infty[\). مجموع وجدّاء وتركيب الدوال المستمرة مستمرين حيث العمليات معرّفة، والقسمة كتحتاج مقاماً غير منعدم.</p>'),
 section('2. Fonction définie par morceaux',r'<p>داخل كل جزء كنستعملو القواعد المعتادة. فـنقطة الربط كنحسبو النهاية اليسارية، النهاية اليمينية والقيمة المعطاة. خاص الثلاثة يتساواو. إذا بارامتر مجهول، هاد التساوي هو اللي كيحدد قيمتو.</p>',example('قيمة البارامتر لضمان الاستمرارية',r'الدالة هي \((x^2-1)/(x-1)\) إذا \(x\ne1\)، و\(f(1)=a\).',[r'لـ \(x\ne1\)، التعبير هو \(x+1\).',r'النهاية فالواحد هي \(2\).',r'الاستمرارية كتفرض أن القيمة \(a\) تساوي هاد النهاية.'],r'\(a=2\).')),
 section('3. Prolongement par continuité',r'<p>إذا الدالة ما معرّفاش فـ \(a\)، ولكن عندها نهاية منتهية \(\ell\)، نقدر نزيد نقطة جديدة بتعريف \(\widetilde f(a)=\ell\). هادي دالة جديدة مستمرة فـ \(a\)، وكتوافق القديمة خارج النقطة. إلا كانت النهاية غير موجودة أو لا نهائية، ما كاينش prolongement حقيقي مستمر بقيمة منتهية.</p>'),
 section('4. TVI : existence ne signifie pas unicité',r'<p>إلا \(f\) مستمرة على \([a,b]\)، فكل عدد بين \(f(a)\) و\(f(b)\) عندو سابق واحد على الأقل فهاد المجال. خصوصاً، إذا \(f(a)f(b)<0\)، فكاين \(\alpha\in]a,b[\) بحيث \(f(\alpha)=0\). باش نثبتو الوحدة، كنكملو بدراسة التزايد التام أو التناقص التام، أو ببرهان آخر.</p>',example('جذر وحيد',r'برهن أن \(x^3+x-1=0\) عندها حل وحيد فـ \(]0,1[\).',[r'\(f(x)=x^3+x-1\) كثيرة حدود، إذن مستمرة على \([0,1]\).',r'\(f(0)=-1\) و\(f(1)=1\)، إذن TVI كيعطي وجود حل.',r'\(f^{\prime}(x)=3x^2+1>0\)، إذن الدالة متزايدة تماماً، والحل وحيد.'],r'كاين حل وحيد \(\alpha\in]0,1[\).')),
 section('5. Dichotomie et encadrement',r'<p>من بعد إثبات الوجود والوحدة، كنأخدو وسط المجال \(m=(a+b)/2\). إذا \(f(m)=0\)، لقينا الجذر وكنوقفو. إلا ماشي صفر، كنحسبو الإشارة ونحتافظو بالنصف اللي فيه تبدّل الإشارة. من بعد \(n\) مراحل مستمرة طول المجال هو \((b-a)/2^n\). إذا أعطينا الوسط كتقريب، الخطأ ما كيتجاوزش نصف الطول.</p><p>فالمثال السابق، \(f(0.68)=-0.005568\) و\(f(0.69)=0.018509\). بالتالي \(0.68<\alpha<0.69\). هاد الحصر كيجي من الإشارة والتزايد، ماشي من تقريب عشوائي ديال الآلة.</p>')],
 [r'الاستمرارية فـ \(a\): نهاية منتهية تساوي \(f(a)\).','فالدوال بالأجزاء، قارن الجهتين بالقيمة.',r'الـ TVI كيحتاج الاستمرارية على المجال المغلق.','الوجود والوحدة خاص كل واحد فيهم تبرير.','فالدّيكوتومي طول الحصر كيتقسم على جوج كل مرة.'],
 ['تساوي النهايتين بوحده ما كافيش إلا كانت قيمة النقطة مختلفة.','تبدّل الإشارة بلا استمرارية ما كيضمنش وجود جذر.','TVI بوحدو ما كيضمنش أن الجذر وحيد.'],[
 exercise('cont-1','ربط جزئين',r'\(f(x)=2x+1\) إذا \(x<1\)، و\(f(x)=ax\) إذا \(x\ge1\). لقى \(a\) باش تكون مستمرة.', 'قارن النهاية من اليسار بقيمة النقطة.',[r'النهاية اليسارية فـ \(1\) هي \(3\).',r'القيمة والنهاية اليمينية هما \(a\).'],r'\(a=3\).'),
 exercise('cont-2','TVI والوحدة',r'برهن أن \(x^3=2\) عندها حل وحيد فـ \(]1,2[\).','استعمل إكس مكعب ناقص جوج.',[r'\(g(x)=x^3-2\) مستمرة على \([1,2]\).',r'\(g(1)=-1\)، \(g(2)=6\)، إذن كاين جذر.',r'\(g^{\prime}(x)=3x^2>0\) على \([1,2]\)، إذن وحيد.'],r'\(\alpha=\sqrt[3]2\in]1,2[\).'),
 exercise('cont-3','حصر عددي',r'حصر الحل السابق بين \(1.25\) و\(1.26\).','حسب مكعب الطرفين.',[r'\(1.25^3=1.953125<2\).',r'\(1.26^3=2.000376>2\).',r'الدالة المكعبة متزايدة تماماً.'],r'\(1.25<\sqrt[3]2<1.26\).')],
 video('نختارو قيمة باش الدالة تولّي مستمرة',
 ('عندنا دالة كتساوي إكس مربع ناقص واحد على إكس ناقص واحد، خارج الواحد. وفالواحد، عطيناها قيمة آ مجهولة.',r'f(x)=\frac{x^2-1}{x-1}\ (x\ne1),\quad f(1)=a','Chercher la continuité en 1'),
 ('باش تكون مستمرة، خاص القيمة فالواحد تساوي الليميت. نبدأو نحسبو الليميت باستعمال التعبير اللي معرّف حدا هاد النقطة.',r'\lim_{x\to1}f(x)=f(1)','Écrire la condition'),
 ('كنحلّلو فرق المربعين. البسط كيولي إكس ناقص واحد مضروب فإكس زائد واحد. نختازلو العامل المشترك حيث إكس مختلف على الواحد.',r'\frac{(x-1)(x+1)}{x-1}=x+1','Simplifier pour x ≠ 1'),
 ('ملي إكس كيقرّب لواحد، إكس زائد واحد كيمشي لجوج. هادي هي النهاية اللي خاص القيمة ديال الدالة توافقها.',r'\lim_{x\to1}(x+1)=2','Calculer la limite'),
 ('إذن خاص آ تكون جوج. هكذا سدّينا الفراغ بالقيمة المناسبة. تذكّر، النهاية وقيمة النقطة خاصهم يتساواو باش نحصلو على الاستمرارية.',r'\boxed{a=2}','Conclure')))
l['goals']=['نبرهن الاستمرارية ونحسب بارامتر الربط.','نستعمل TVI لإثبات الوجود.','نثبت الوحدة ونعطي حصراً.'];l['prerequisites']=['limites','formes-indeterminees'];l['quiz']=[dict(question='TVI كيبرهن بوحدو على شنو؟',choices=['وجود سابق واحد على الأقل','وحدة السابق دائماً','قابلية الاشتقاق'],correct=0,explanation='الوحدة كتحتاج شرطاً إضافياً بحال الرتابة التامة.')]

l=lesson('derivation','Dérivation et tangentes','الاشتقاق والمماس',
 'المشتقة كتقيس التغيّر المحلي ديال الدالة، وكتعطي الميل ديال المماس. ما نحفظوش غير القواعد، خاصنا نعرفو فاش نطبقوها وشنو كتسمح لينا نستنتجو على المنحنى.',[
 section('1. Nombre dérivé et interprétation',r'<p>الدالة قابلة للاشتقاق فـ \(a\) إلا كانت النهاية \[f^{\prime}(a)=\lim_{h\to0}\frac{f(a+h)-f(a)}h\] موجودة ومنتهية. هاد العدد هو ميل المماس، ومعادلتو \[y=f(a)+f^{\prime}(a)(x-a).\]</p><p>قابلية الاشتقاق كتفرض الاستمرارية. العكس غير صحيح: \(|x|\) مستمرة فالصفر، ولكن المشتقة اليسارية \(-1\) واليمينية \(1\)، إذن ماشي قابلة للاشتقاق تماك. نهاية لا نهائية لمعدل التغيّر تقدر تشير لنصف مماس عمودي، وماشي مشتقة منتهية.</p>'),
 section('2. Tableau des dérivées usuelles',r'<p>\((x^n)^{\prime}=nx^{n-1}\)، \((1/x)^{\prime}=-1/x^2\)، \((\sqrt{x})^{\prime}=1/(2\sqrt{x})\) لـ \(x>0\). وعندنا \((\ln x)^{\prime}=1/x\) لـ \(x>0\)، \((e^x)^{\prime}=e^x\)، \((\sin x)^{\prime}=\cos x\)، \((\cos x)^{\prime}=-\sin x\).</p><p>بالنسبة للقوة العقلانية كنخدمو على المجالات اللي فيها الدالة معرّفة وقابلة للاشتقاق. بصفة آمنة على \(x>0\)، \((x^r)^{\prime}=rx^{r-1}\) لكل \(r\in\mathbb Q\). الصيغ فالنقط الحدودية كتحتاج دراسة منفصلة.</p>'),
 section('3. Somme, produit, quotient et composée',r'<p>\[(u+v)^{\prime}=u^{\prime}+v^{\prime},\qquad(uv)^{\prime}=u^{\prime} v+uv^{\prime}.\]\[\left(\frac uv\right)^{\prime}=\frac{u^{\prime} v-uv^{\prime}}{v^2}\quad(v\ne0).\]التركيب هو \((g\circ u)^{\prime}(x)=u^{\prime}(x)g^{\prime}(u(x))\). مثلاً \((\ln u)^{\prime}=u^{\prime}/u\) إذا \(u>0\)، و\((e^u)^{\prime}=u^{\prime} e^u\). خاص نكتب الدالة الداخلية ومشتقتها باش ما ننساش العامل.</p>',example('تركيب مع الجداء',r'اشتق \(f(x)=x^2e^{3x}\).',[r'\(u=x^2\) و\(v=e^{3x}\)، إذن \(u^{\prime}=2x\) و\(v^{\prime}=3e^{3x}\).',r'\(f^{\prime}=2xe^{3x}+3x^2e^{3x}\).',r'كنخرجو العامل المشترك لقراءة الإشارة من بعد.'],r'\(f^{\prime}(x)=xe^{3x}(2+3x)\).')),
 section('4. Variations, extrema et seconde dérivée',r'<p>على مجال، إذا \(f^{\prime}\ge0\) فـ \(f\) متزايدة، وإذا \(f^{\prime}\le0\) فهي متناقصة. إذا المشتقة موجبة تماماً، نحصلو على تزايد تام. انعدام المشتقة فبعض النقط المعزولة ما كيمنعش بالضرورة التزايد التام.</p><p>فالنقطة الداخلية \(a\)، انتقال الإشارة من سالب لموجب كيعطي minimum local، والعكس maximum local. شرط \(f^{\prime}(a)=0\) بوحده ما كافيش: \(x^3\) ما عندهاش extremum فالصفر. إذا \(f^{\prime\prime}>0\) فالمنحنى convex، وإذا سالبة concave. نقطة الانعطاف كتحتاج تبدّل التقعّر، ماشي غير \(f^{\prime\prime}=0\).</p>'),
 section('5. Tangente et approximation locale',r'<p>فالقرب من \(a\)، الدالة كتتقرب بالكتابة \(f(a+h)\approx f(a)+hf^{\prime}(a)\). هادي تقريب محلي وماشي مساواة عامة. باش نرسمو المماس كنحتاجو القيمة والمشتقة فالنقطة بجوج، ثم كنراقبو واش المستقيم كيدوز من \((a,f(a))\).</p>',example('مماس دالة مكعبة',r'لقى معادلة المماس لـ \(f(x)=x^3-3x\) فـ \(a=2\).',[r'\(f(2)=8-6=2\).',r'\(f^{\prime}(x)=3x^2-3\)، إذن \(f^{\prime}(2)=9\).',r'\(y=2+9(x-2)\).'],r'\(y=9x-16\).'))],
 [r'قابلية الاشتقاق كتفرض الاستمرارية.','فمشتقة التركيب، ما تنساش مشتقة الداخل.',r'فالقسمة، المقام هو \(v^2\) والإشارة ناقص.',r'المماس: \(y=f(a)+f^{\prime}(a)(x-a)\).','جدول الإشارة هو اللي كيعطي التغيّرات.'],
 ['مشتقة جداء ماشي جداء المشتقات.','انعدام المشتقة ما كيضمنش extremum.','القابلية للاشتقاق فحدود المجال خاصها تحقق خاص.'],[
 exercise('der-1','مشتقة كسر',r'اشتق \(f(x)=\frac{x+1}{x-1}\).','المقام غير منعدم.',[r'المجال \(\mathbb R\setminus\{1\}\).',r'\(f^{\prime}=\frac{(x-1)-(x+1)}{(x-1)^2}\).'],r'\(f^{\prime}(x)=-2/(x-1)^2\).'),
 exercise('der-2','مماس',r'مماس \(f(x)=\ln x\) فـ \(x=1\).','حسب القيمة والميل.',[r'\(f(1)=0\).',r'\(f^{\prime}(1)=1\).',r'\(y=0+1(x-1)\).'],r'\(y=x-1\).'),
 exercise('der-3','نقطة ماشي extremum',r'واش \(f(x)=x^3\) عندها extremum فالصفر؟','قرا إشارة المشتقة على جهتي الصفر.',[r'\(f^{\prime}(x)=3x^2\ge0\).',r'الإشارة ما تبدلاتش من تزايد لتناقص أو العكس.',r'كتوجد قيم سالبة قبل الصفر وموجبة من بعد.'],r'لا. عندها نقطة انعطاف ومماس أفقي فالصفر.')],
 video('نحسبو المماس بلا ما ننسّاو القيمة',
 ('عندنا إيف ديال إكس كتساوي إكس مكعب ناقص ثلاثة إكس. بغينا المماس فالنقطة اللي الفاصلة ديالها جوج.',r'f(x)=x^3-3x,\quad a=2','Chercher la tangente'),
 ('أول حاجة نحسبو ارتفاع النقطة. نعوضو إكس بجوج، كنلقاو ثمانية ناقص ستة، يعني جوج. إذن النقطة عندها الإحداثيات جوج وجوج.',r'f(2)=2^3-3\times2=2','Calculer le point'),
 ('دابا نشتقو. مشتقة إكس مكعب هي ثلاثة إكس مربع، ومشتقة ناقص ثلاثة إكس هي ناقص ثلاثة. هادي كتعطينا دالة الميل.',r'f^{\prime}(x)=3x^2-3','Calculer la dérivée'),
 ('فالجوج، الميل هو ثلاثة مرات ربعة ناقص ثلاثة، يعني تسعود. كنستعملو معادلة المماس بالقيمة والميل اللي حسبنا.',r'f^{\prime}(2)=9,\quad y=2+9(x-2)','Utiliser le point et la pente'),
 ('كنطورو ونبسطو. كتولي إيگريك كتساوي تسعود إكس ناقص ستّاش. كنراقبو: إلا عوضنا إكس بجوج، كنرجعو لجوج، قيمة النقطة.',r'\boxed{y=9x-16}','Vérifier le résultat')))
l['goals']=['نحسب المشتقة مع المجال.','نكتب المماس ونربط المشتقة بالتغيّرات.','نميّز extrema ونقط الانعطاف.'];l['prerequisites']=['limites','continuite'];l['quiz']=[dict(question=r'مشتقة \(e^{2x}\) هي؟',choices=[r'\(e^{2x}\)',r'\(2e^{2x}\)',r'\(e^2\)'],correct=1,explanation='قاعدة التركيب كتفرض الضرب فمشتقة 2x، وهي 2.')]

l=lesson('etude-fonction','Étude complète d’une fonction','دراسة كاملة لدالة',
 'الدراسة الكاملة ماشي حساب مشتقة فقط. كنربطو المجال، الحدود، المقاربات، التغيّرات، التقعّر، والتقاطعات باش الرسم النهائي يكون نتيجة للبرهان.',[
 section('1. Un plan de travail qui évite les oublis',r'<p>الترتيب العملي هو: المجال، التماثل إذا كان مفيداً، الحدود فحدود المجال، المقاربات، المشتقة وإشارتها، جدول التغيّرات، القيم المهمة والمماس، ثم الرسم. إذا مطلوب التقعّر، كنزيدو المشتقة الثانية ونقط الانعطاف. وإذا معادلة \(f(x)=m\)، كنستعملو فروع التغيّر باش نعدّو الحلول.</p><p>فكل فرع من المجال خاص نهاية البداية ونهاية النهاية. فجدول التغيّرات، القيمة الممنوعة كتبقى مفصولة، وما كنرسموش سهم كيدوز من خلال مقارب عمودي.</p>'),
 section('2. Exemple central : domaine et décomposition',r'<p>ندرسو \[f(x)=\frac{x^2+1}{x-1}.\]المجال هو \(\mathbb R\setminus\{1\}\). بالقسمة كنلقاو \[f(x)=x+1+\frac2{x-1}.\]هاد الكتابة كتسهل الحدود والمشتقة والمقارب.</p><p>عند \(1^-\)، \(2/(x-1)\to-\infty\)، وعند \(1^+\) كيمشي لـ \(+\infty\). إذن \(x=1\) مقارب عمودي. فـ \(\pm\infty\)، الفرق \(f(x)-(x+1)=2/(x-1)\to0\)، إذن \(y=x+1\) مقارب مائل.</p>'),
 section('3. Dérivée, signe et tableau des variations',r'<p>\[f^{\prime}(x)=1-\frac2{(x-1)^2}=\frac{(x-1)^2-2}{(x-1)^2}.\]المقام موجب. الجذور ديال البسط هما \(a=1-\sqrt2\) و\(b=1+\sqrt2\). المشتقة موجبة خارج \([a,b]\) وسالبة داخلو، مع فصل \(1\).</p><ul><li>تزايد على \(]-\infty,a]\)، من \(-\infty\) حتى \(2-2\sqrt2\).</li><li>تناقص على \([a,1[\)، حتى \(-\infty\).</li><li>تناقص على \(]1,b]\)، من \(+\infty\) حتى \(2+2\sqrt2\).</li><li>تزايد على \([b,+\infty[\)، حتى \(+\infty\).</li></ul><p>إذن \(a\) موضع maximum local، و\(b\) موضع minimum local. القيم كتتحسب باستعمال الكتابة المفككة.</p>'),
 section('4. Position, intersections et concavité',r'<p>\(f(x)-(x+1)=2/(x-1)\): المنحنى تحت المقارب إذا \(x<1\)، وفوقو إذا \(x>1\). عند \(x=0\)، \(f(0)=-1\)، إذن كيدوز من \((0,-1)\). ما كيقطعش محور الفواصل لأن \(x^2+1>0\) دائماً.</p><p>المشتقة الثانية هي \(f^{\prime\prime}(x)=4/(x-1)^3\). المنحنى concave على \(]-\infty,1[\) وconvexe على \(]1,+\infty[\). ما كايناش نقطة انعطاف فـ \(1\)، حيث النقطة خارج المجال رغم تبدّل الإشارة.</p><p>مركز التناظر هو \((1,2)\)، لأن \(f(1+h)+f(1-h)=4\) لكل \(h\ne0\).</p>'),
 section('5. Tangente et dessin justifié',r'<p>فالصفر، \(f(0)=-1\) و\(f^{\prime}(0)=-1\). إذن المماس هو \(y=-x-1\). فالرسم كنثبتو المقاربين، النقطة \((0,-1)\)، القيم القصوى، واتجاه الأسهم. كنحترمو أن الفرعين ما كيتلاقاوش فـ \(x=1\)، وأن موضعهما بالنسبة للمقارب محدد بالإشارة.</p><p>الرسم التقريبي ما يعوّضش الحساب. إلا بان تناقض بين الرسم والجدول، كنرجعو للإشارة والحدود قبل ما نكمّلو.</p>'),
 section('6. Une étude de fonction logarithmique',r'<p>كنأخدو \(g(x)=x-1-\ln x\) على \(]0,+\infty[\). عند \(0^+\)، النهاية \(+\infty\). وعند \(+\infty\)، نكتب \(g(x)=x(1-1/x-\ln x/x)\to+\infty\). المشتقة \(g^{\prime}(x)=(x-1)/x\) سالبة قبل \(1\) وموجبة بعده.</p><p>إذن \(g\) عندها minimum global فـ \(1\)، وقيمتو \(0\). كنستنتجو المتراجحة المهمة \(\ln x\le x-1\) لكل \(x>0\)، مع المساواة فقط فـ \(x=1\). هنا دراسة الدالة ولّات برهان لمتراجحة.</p>')],
 ['كتب المجال قبل أي تحويل.','دير كل الحدود اللي كيحتاجها كل فرع.','جدول التغيّرات مبني على إشارة المشتقة.','المقارب المائل خاص فرق كيمشي للصفر.','الرسم يجمع النتائج وما يعوّضهاش.'],
 ['ما تعتبَرش قيمة ممنوعة نقطة انعطاف.','maximum local ماشي بالضرورة maximum على المجال كامل.','القسمة على إكس فحد عند الصفر مختلفة على اللانهاية.'],[
 exercise('etud-1','دراسة كثيرة حدود',r'درس تغيّرات \(f(x)=x^3-3x\).','حلّل المشتقة.',[r'المجال هو \(\mathbb R\)، والحدود هما \(-\infty,+\infty\).',r'\(f^{\prime}(x)=3(x-1)(x+1)\).',r'تزايد على \(]-\infty,-1]\)، تناقص على \([-1,1]\)، ثم تزايد على \([1,+\infty[\).',r'\(f(-1)=2\)، \(f(1)=-2\).'],r'maximum local عند \(-1\) قيمته \(2\)، minimum local عند \(1\) قيمته \(-2\).'),
 exercise('etud-2','متراجحة أسية',r'برهن \(e^x\ge1+x\) لكل \(x\in\mathbb R\).','درس h(x)=exp(x)-1-x.',[r'\(h^{\prime}(x)=e^x-1\)، سالبة إذا \(x<0\) وموجبة إذا \(x>0\).',r'\(h\) عندها minimum global فـ \(0\).',r'\(h(0)=0\).'],r'\(e^x-1-x\ge0\)، المساواة فقط فالصفر.'),
 exercise('etud-3','عدد الحلول',r'باستعمال المثال الرئيسي، شحال من حل للمعادلة \(f(x)=2\)؟','قارن 2 مع القيم اللي كياخدها كل فرع.',[r'الفرع اليساري كياخد قيماً \(\le2-2\sqrt2<2\).',r'الفرع اليميني كياخد قيماً \(\ge2+2\sqrt2>2\).',r'أو نحسب \(x^2+1=2x-2\)، أي \((x-1)^2+2=0\)، مستحيلة فالأعداد الحقيقية.'],r'ما كاين حتى حل حقيقي.')],
 video('دراسة التغيّرات ديال دالة مكعبة',
 ('غادي ندرسو تغيّرات إكس مكعب ناقص ثلاثة إكس. الدالة معرّفة على الأعداد الحقيقية كاملة، وحدودها فالجهتين سالبة وموجبة لانفيني.',r'f(x)=x^3-3x,\quad D_f=\mathbb{R}','Domaine et limites'),
 ('المشتقة هي ثلاثة إكس مربع ناقص ثلاثة. كنحللوها لثلاثة، مضروبة فإكس ناقص واحد، مضروبة فإكس زائد واحد.',r'f^{\prime}(x)=3(x-1)(x+1)','Factoriser la dérivée'),
 ('المشتقة كتعدم فناقص واحد وواحد. إشارة الجداء موجبة قبل ناقص واحد، سالبة بينهما، وموجبة من بعد الواحد.',r'f^{\prime}>0\ \text{hors }[-1,1],\quad f^{\prime}<0\ \text{sur }]-1,1[','Étudier le signe'),
 ('إذن الدالة كتطلع، من بعد كتهبط، ومن بعد كتطلع. نحسبو قيمتها فالنقط المهمة، كنلقاو جوج فناقص واحد، وناقص جوج فالواحد.',r'f(-1)=2,\qquad f(1)=-2','Calculer les valeurs remarquables'),
 ('عندنا قيمة قصوى محلية جوج، وقيمة دنيا محلية ناقص جوج. جدول التغيّرات كيحط هاد النتائج مع الحدود، باش الرسم يكون مبني على الحساب.',r'-\infty\nearrow2\searrow-2\nearrow+\infty','Construire le tableau')))
l['duration']=65;l['goals']=['ننجز دراسة كاملة لكسر أو دالة ln/exp.','نربط الجداول بالمقاربات والرسم.','نستعمل الدراسة لحل متراجحة أو عدّ الحلول.'];l['prerequisites']=['limites','derivation','continuite'];l['quiz']=[dict(question='إلا تغيّرت إشارة f″ عند نقطة خارج المجال، واش هادي نقطة انعطاف؟',choices=['نعم دائماً','لا، خاص النقطة تنتمي للمنحنى','غير إذا f′ كتعدم'],correct=1,explanation='نقطة الانعطاف خاصها تكون نقطة من المنحنى مع تغير التقعر.')]

l=lesson('suites','Suites numériques et récurrence','المتتاليات العددية والاستدلال بالتراجع',
 'المتتالية كتعطي عدداً لكل رتبة طبيعية. كنميّزو الصيغة المباشرة عن التعريف بالتراجع، وكنربطو الرتابة والحصر بالنهاية. حل معادلة النقطة الثابتة وحده ما كيبرهنش التقارب.',[
 section('1. Suites arithmétiques et géométriques',r'<p>إذا \(u_{n+1}=u_n+r\)، فالمتتالية arithmétique و\(u_n=u_0+nr\). مجموع \(n+1\) حدود من \(u_0\) حتى \(u_n\) هو \((n+1)(u_0+u_n)/2\).</p><p>إذا \(u_{n+1}=qu_n\)، فـ \(u_n=u_0q^n\). إذا \(q\ne1\)، \(\sum_{k=0}^nq^k=(1-q^{n+1})/(1-q)\). إذا \(|q|<1\)، \(q^n\to0\). إذا \(q>1\)، \(q^n\to+\infty\). المتتالية \(q^n\) كتتناوب بلا تقارب عند \(q=-1\)، وعند \(q<-1\) تتناوب إشارتها مع قيم مطلقة كتكبر. بالنسبة لـ \(u_n=u_0q^n\)، هاد عدم التقارب كيحتاج \(u_0\ne0\). إذا \(u_0=0\)، فالمتتالية كلها صفر مهما كانت \(q\).</p>'),
 section('2. Récurrence, invariance et monotonie',r'<p>برهان التراجع كيحتاج البداية، ثم الفرضية فالرتبة \(n\)، ثم الاستنتاج فالرتبة \(n+1\). فمتتالية \(u_{n+1}=f(u_n)\)، إثبات \(f(I)\subset I\) مع \(u_0\in I\) كيضمن أن جميع الحدود باقية فـ \(I\).</p><p>الرتابة كنثبتوها بإشارة \(u_{n+1}-u_n\). النسبة \(u_{n+1}/u_n\) كتعاون غير مع شروط الإشارة وعدم الانعدام. ما نستنتجوش رتابة المتتالية غير من كون الدالة \(f\) متزايدة بلا النظر للبداية.</p>'),
 section('3. Suite arithmético-géométrique',r'<p>بالنسبة لـ \(u_{n+1}=au_n+b\)، إذا \(a\ne1\)، نلقى النقطة الثابتة \(\ell=b/(1-a)\)، ثم نحط \(v_n=u_n-\ell\). كنلقاو \(v_{n+1}=av_n\)، إذن \[u_n=\ell+(u_0-\ell)a^n.\]إذا \(|a|<1\) فـ \(u_n\to\ell\). إذا \(a=1\)، كترجع arithmétique.</p>',example('متتالية تقترب من 6',r'\(u_0=0\)، \(u_{n+1}=u_n/2+3\).',[r'النقطة الثابتة كتتحل من \(\ell=\ell/2+3\)، إذن \(\ell=6\).',r'\(v_n=u_n-6\)، ومنه \(v_{n+1}=v_n/2\) و\(v_0=-6\).',r'\(v_n=-6(1/2)^n\).'],r'\(u_n=6-6/2^n\)، والنهاية \(6\).')),
 section('4. Convergence et point fixe',r'<p>المتتالية المتزايدة والمحدودة من الفوق متقاربة. والمتناقصة والمحدودة من التحت حتى هي متقاربة. من بعد إثبات التقارب، إذا \(u_{n+1}=f(u_n)\) و\(f\) مستمرة فالنهاية، نقدر نمر للحدود ونكتب \(\ell=f(\ell)\).</p><p>معادلة النقطة الثابتة كتحدد المرشحين للنهاية، ولكن ما كتثبتش وجود النهاية. كنستعملو الحصر باش نختارو الحل الموافق، وبراهين التراجع باش نثبتو بقاء المتتالية فمجال صالح.</p>'),
 section('5. Exemple non linéaire',r'<p>نأخدو \(u_0=0\) و\(u_{n+1}=\sqrt{2+u_n}\). بالتراجع، \(0\le u_n\le2\). على \([0,2]\)، عندنا \(\sqrt{2+x}\ge x\)، حيث \(2+x-x^2=(2-x)(x+1)\ge0\). إذن المتتالية متزايدة ومحدودة، فهي متقاربة.</p><p>بالاستمرارية \(\ell=\sqrt{2+\ell}\)، أي \(\ell^2-\ell-2=0\). الجذران \(2,-1\)، وبما أن \(\ell\in[0,2]\)، النهاية هي \(2\).</p>')],
 ['تأكد واش الرتبة كاتبدا بصفر أو واحد.','التراجع كيحتاج البداية والانتقال.','الرتابة والحصر يقدرو يثبتو التقارب.',r'فـ \(u_{n+1}=au_n+b\)، النقطة الثابتة كتسهّل التبديل.','حل معادلة الحد كيجي بعد إثبات التقارب.'],
 ['ما تعوّضش متتالية بنهايتها قبل إثبات أنها متقاربة.','المجموع من صفر لنون فيه نون زائد واحد حدود.','إذا النسبة سالبة، الرتابة ماشي مباشرة.'],[
 exercise('suite-1','صيغة صريحة',r'\(u_0=2\)، \(u_{n+1}=3u_n\). حسب \(u_n\) و\(\sum_{k=0}^nu_k\).','متتالية هندسية.',[r'\(u_n=2\cdot3^n\).',r'المجموع \(2(3^{n+1}-1)/(3-1)\).'],r'\(S_n=3^{n+1}-1\).'),
 exercise('suite-2','تقارب متتالية affine',r'\(u_0=1\)، \(u_{n+1}=u_n/3+2\).','النقطة الثابتة هي 3.',[r'\(v_n=u_n-3\) كتتحقق فيها \(v_{n+1}=v_n/3\).',r'\(v_0=-2\)، إذن \(u_n=3-2/3^n\).',r'\(3^{-n}\to0\).'],r'\(u_n\to3\).'),
 exercise('suite-3','حصر نهاية',r'إذا \(n\le u_n\le n+1\)، حسب \(\lim u_n/n\) لـ \(n\ge1\).','قسم المتراجحة على عدد موجب.',[r'\(1\le u_n/n\le1+1/n\).',r'الطرفان كيمشيو لواحد.'],r'بالحصر، النهاية \(1\).')],
 video('نحوّلو متتالية لمتتالية هندسية',
 ('عندنا يو صفر كتساوي صفر، وكل حد جديد هو نصف الحد السابق زائد ثلاثة. بغينا الصيغة والنهاية بطريقة واضحة.',r'u_0=0,\qquad u_{n+1}=\frac12u_n+3','Lire la récurrence'),
 ('كنقلبو أولاً على العدد اللي ما كيتبدلش. نحلو إل كتساوي نصف إل زائد ثلاثة، وكنلقاو ستة. هادي النقطة الثابتة.',r'\ell=\frac12\ell+3\ \Longrightarrow\ \ell=6','Trouver le point fixe'),
 ('كنحطو ڤي نون كتساوي يو نون ناقص ستة. باستعمال العلاقة، الحد الجديد ديال ڤي كيولي نصف الحد السابق بالضبط.',r'v_n=u_n-6,\qquad v_{n+1}=\frac12v_n','Obtenir une suite géométrique'),
 ('ڤي صفر هي ناقص ستة. إذن ڤي نون هي ناقص ستة مضروبة فنصف أُس نون. نرجعو ليو بإضافة ستة.',r'u_n=6-6\left(\frac12\right)^n','Revenir à u'),
 ('نصف أُس نون كتمشي للصفر، إذن يو نون كتمشي لستة. الصيغة كتعطينا حتى أنها متزايدة وباقية أصغر من ستة.',r'\boxed{\lim u_n=6}','Conclure')))
l['prerequisites']=['limites','continuite'];l['goals']=['نثبت الرتابة والحصر بالتراجع.','نحل التراجع affine.','نبرهن التقارب ثم نحدد النهاية.'];l['quiz']=[dict(question='حل ℓ=f(ℓ) كافي بوحدو لإثبات تقارب المتتالية؟',choices=['نعم','لا، غير كيحدد النهايات المحتملة'],correct=1,explanation='خاص برهان للتقارب، مثلاً الرتابة والحصر، قبل المرور للحدود.')]

l=lesson('fonctions-reciproques','Fonctions réciproques et puissances','الدالة العكسية والقوى',
 'الدالة العكسية كترجعنا من الصورة للسابق. كنحتاجو نضمنو أن كل صورة عندها سابق وحيد، وكنحددوا المجال والصورة قبل ما نكتبو العكس.',[
 section('1. Bijection sur un intervalle',r'<p>إذا \(f\) مستمرة ومتزايدة أو متناقصة تماماً على مجال \(I\)، فهي bijection من \(I\) إلى \(J=f(I)\). الصورة كتتحسب بالقيم أو الحدود فطرفي المجال، مع احترام واش الحدود داخلة. لكل \(y\in J\)، كاين \(x\in I\) وحيد بحيث \(f(x)=y\).</p><p>الدالة العكسية \(f^{-1}:J\to I\) مستمرة وعندها نفس اتجاه التغيّر. الكتابة \(f^{-1}\) ماشي \(1/f\). التماثل بالنسبة للمستقيم \(y=x\) كيربط المنحنيين فمعلم متعامد ومتجانس.</p>'),
 section('2. Trouver une expression et son domaine',r'<p>باش نلقى العكس، كنكتب \(y=f(x)\)، كنحل على \(x\) باحترام المجال الأصلي، ومن بعد كنسمّي المتغيّر الجديد كيف بغيت. ممكن نفس الصيغة تعطي جوج فروع إذا ما حددناش المجال من الأول.</p>',example('عكس مربع على نصف مستقيم',r'\(f(x)=x^2+1\) على \([0,+\infty[\).',[r'\(f\) مستمرة ومتزايدة تماماً على هاد المجال.',r'الصورة هي \([1,+\infty[\).',r'من \(y=x^2+1\) و\(x\ge0\)، كنلقاو \(x=\sqrt{y-1}\).'],r'\(f^{-1}(y)=\sqrt{y-1}\) لـ \(y\ge1\).')),
 section('3. Dérivée de la réciproque',r'<p>تحت فرضيات التقابل السابقة، ومع \(a\) نقطة داخلية فـ \(I\)، إذا \(f\) قابلة للاشتقاق فـ \(a\) والمشتقة \(f^{\prime}(a)\ne0\)، فعكسها قابل للاشتقاق فـ \(b=f(a)\)، و\[(f^{-1})^{\prime}(b)=\frac1{f^{\prime}(a)}.\]بصيغة عامة \((f^{-1})^{\prime}(x)=1/f^{\prime}(f^{-1}(x))\)، حيث الشروط متحققة.</p><p>فالمثال السابق، عند \(a=2\) كنلقاو \(b=5\) و\(f^{\prime}(2)=4\)، إذن \((f^{-1})^{\prime}(5)=1/4\). فـ \(a=0\) المشتقة منعدمة، والصيغة ما صالحةش. فعلاً العكس \(\sqrt{y-1}\) عندو نصف مماس عمودي فـ \(1\).</p>'),
 section('4. Racines n-ièmes et puissances rationnelles',r'<p>بالنسبة لـ \(n\in\mathbb{N}^*\)، الدالة \(x\mapsto x^n\) على \([0,+\infty[\) عندها عكس \(x\mapsto\sqrt[n]x\). إذا \(n\) فردي، كاين عكس حتى على \(\mathbb R\). على \(x>0\)، كنعرّفو \(x^{p/q}=(\sqrt[q]x)^p\) بالنسبة لـ \(q>0\)، والقواعد \(x^rx^s=x^{r+s}\)، \((x^r)^s=x^{rs}\) كتخدم هاد المجال.</p><p>\((x^r)^{\prime}=rx^{r-1}\) لـ \(x>0\). فالصفر والأعداد السالبة كيرجع المجال للمعنى الدقيق ديال الأس، وما نعمّموش الصيغ على تعابير غير معرّفة.</p>')],
 ['حدّد المجال والصورة قبل كتابة العكس.','الاستمرارية والرتابة التامة كيضمنو bijection.',r'\(f^{-1}\ne1/f\) بصفة عامة.',r'مشتقة العكس هي مقلوب المشتقة فالسابق، بشرط عدم انعدامها.','القوى العقلانية على المجال الموجب كتجنب التباس التعريف.'],
 ['ما تختارش جذر سالب إذا المجال الأصلي موجب.','ما تعوّضش صورة فمكان السابق فصيغة مشتقة العكس.','مشتقة الأصل المنعدمة كتمنع استعمال صيغة المقلوب مباشرة.'],[
 exercise('inv-1','دالة affine',r'لقى عكس \(f(x)=3x-2\) على \(\mathbb R\).','حل المعادلة y=3x-2 على x.',[r'الدالة مستمرة ومتزايدة تماماً، وصورتها \(\mathbb R\).',r'\(y=3x-2\Rightarrow x=(y+2)/3\).'],r'\(f^{-1}(x)=(x+2)/3\).'),
 exercise('inv-2','مشتقة بدون صيغة العكس',r'\(f(x)=x^3+x\) على \(\mathbb R\). حسب \((f^{-1})^{\prime}(2)\).','لقى السابق ديال 2.',[r'\(f^{\prime}(x)=3x^2+1>0\)، والدالة مستمرة وحدودها \(\pm\infty\)، إذن bijection على \(\mathbb R\).',r'\(f(1)=2\) و\(f^{\prime}(1)=4\).'],r'\((f^{-1})^{\prime}(2)=1/4\).'),
 exercise('inv-3','قوة عقلانية',r'اشتق \(f(x)=x^{3/2}\) على \(]0,+\infty[\).','طبق قاعدة القوة.',[r'\(r=3/2\)، إذن \(r-1=1/2\).',r'المجال موجب، قاعدة الاشتقاق صالحة.'],r'\(f^{\prime}(x)=\frac32\sqrt{x}\).')],
 video('مشتقة العكس بلا ما نلقاو صيغتو',
 ('إيف ديال إكس هي إكس مكعب زائد إكس. بغينا مشتقة الدالة العكسية فالجوج، وغادي نحسبوها بلا ما نلقاو صيغة العكس.',r'f(x)=x^3+x,\quad (f^{-1})^{\prime}(2)\ ?','Dérivée de la réciproque'),
 ('المشتقة ديال إيف هي ثلاثة إكس مربع زائد واحد، موجبة دائماً. مع الاستمرارية والحدود فاللانهاية، الدالة كتحدد تقابلاً على الأعداد الحقيقية.',r'f^{\prime}(x)=3x^2+1>0','Justifier la bijection'),
 ('خاصنا نلقاو السابق ديال جوج. نجربو الواحد، واحد مكعب زائد واحد كتعطينا جوج. إذن العكس ديال جوج هو واحد.',r'f(1)=2\quad\Longrightarrow\quad f^{-1}(2)=1','Trouver le bon antécédent'),
 ('نحسبو المشتقة فالواحد، كنلقاو ربعة، اللي ماشي صفر. دابا نقدروا نطبقو قاعدة مشتقة العكس باستعمال المقلوب.',r'f^{\prime}(1)=4\ne0','Vérifier le dénominateur'),
 ('مشتقة العكس فالجوج هي واحد على مشتقة الأصل فالواحد، يعني الربع. رد البال، كنحسبو مشتقة الأصل فالسابق، ماشي فالصورة.',r'\boxed{(f^{-1})^{\prime}(2)=\frac14}','Conclure')))
l['prerequisites']=['continuite','derivation'];l['goals']=['نثبت التقابل ونحدد صورة المجال.','نحسب العكس مع الشروط.','نستعمل صيغة مشتقة العكس.'];l['quiz']=[dict(question=r'واش \(f^{-1}(x)\) كتساوي دائماً \(1/f(x)\)؟',choices=['نعم','لا'],correct=1,explanation='الأولى دالة عكسية ديال تقابل، والثانية مقلوب قيمة عددية.')]

